def require_disjoint_splits(split_to_ids):
    names = list(split_to_ids)
    for i, left in enumerate(names):
        for right in names[i + 1:]:
            overlap = set(split_to_ids[left]) & set(split_to_ids[right])
            if overlap:
                examples = sorted(overlap)[:3]
                raise ValueError(
                    f"{left}/{right} identity leak: {examples}"
                )

example_splits = {
    "train": {"series-001", "series-002"},
    "validation": {"series-101"},
    "test": {"series-201"},
}
require_disjoint_splits(example_splits)
